-- A Shopify webhook names its shop and nothing else (P6-06, ADR 0031), so the winery that holds the shop is learned from this table before any tenant is known.
-- The branch admits the one row for the shop the flag names, on this table only, and only resolveTenantByShop sets it, inside a READ ONLY transaction, before handing over to withTenant.
-- WITH CHECK stays tenant-only.
ALTER TABLE shopify_installations ENABLE ROW LEVEL SECURITY;
ALTER TABLE shopify_installations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON shopify_installations
  USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid
    OR shop = nullif(current_setting('app.shopify_shop', true), ''))
  WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid);
