-- The install callback is a redirect from Shopify and carries no tenant, so it finds the state in the scope of the member who started the install — the memberships argument, on one more table.
-- It spends the state by deleting it, which only USING governs; WITH CHECK stays tenant-only, so the user scope cannot write a state naming any winery.
ALTER TABLE shopify_oauth_states ENABLE ROW LEVEL SECURITY;
ALTER TABLE shopify_oauth_states FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON shopify_oauth_states
  USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid
    OR user_id = nullif(current_setting('app.user_id', true), ''))
  WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid);
